import unittest


class TestExchange(unittest.TestCase):

    def test_all_even_lst1_empty_lst2(self):
        # No odd numbers to exchange, should be YES
        self.assertEqual(exchange([2, 4, 6], []), "YES")

    def test_equal_counts(self):
        # One odd in lst1, one even in lst2 -> exchange possible
        self.assertEqual(exchange([1, 2, 3], [2, 4]), "YES")

    def test_enough_evens(self):
        # More evens in lst2 than odds in lst1
        self.assertEqual(exchange([1, 5, 3], [2, 4, 6, 8]), "YES")

    def test_not_enough_evens(self):
        # More odds in lst1 than evens in lst2
        self.assertEqual(exchange([1, 3, 5], [2]), "NO")

    def test_no_odds_no_evens(self):
        self.assertEqual(exchange([2, 4], [1, 3]), "YES")

    def test_all_odd_all_odd(self):
        self.assertEqual(exchange([1, 3], [5, 7]), "NO")

    def test_empty_both(self):
        self.assertEqual(exchange([], []), "YES")

    def test_empty_lst1(self):
        self.assertEqual(exchange([], [2, 4]), "YES")

    def test_empty_lst2(self):
        self.assertEqual(exchange([1, 2], []), "NO")

    def test_negative_numbers(self):
        # Negative odd: -3 % 2 == 1 in Python, negative even: -2 % 2 == 0
        self.assertEqual(exchange([-3, 2], [-2, 4]), "YES")
        self.assertEqual(exchange([-3, -5], [-2]), "NO")

    def test_single_elements(self):
        self.assertEqual(exchange([1], [2]), "YES")
        self.assertEqual(exchange([1], [3]), "NO")
        self.assertEqual(exchange([2], [2]), "YES")

    def test_large_lists(self):
        lst1 = list(range(1, 51))          # 25 odds
        lst2 = list(range(2, 102, 2))      # 50 evens
        self.assertEqual(exchange(lst1, lst2), "YES")
        self.assertEqual(exchange(lst1, [2]), "NO")

    def test_zero_is_even(self):
        self.assertEqual(exchange([1], [0]), "YES")
        self.assertEqual(exchange([1, 3], [0]), "NO")


